-- P02 adds explicit trust metadata. Legacy records remain untrusted; no
-- credential, target key, or immutable object version is fabricated.
ALTER TABLE targets ADD COLUMN target_key varchar(128), ADD COLUMN contract_version varchar(64), ADD COLUMN credential_provider varchar(32), ADD COLUMN credential_reference varchar(128), ADD COLUMN transport_policy_version varchar(64), ADD COLUMN registration_hash varchar(71), ADD COLUMN trust_metadata_complete boolean NOT NULL DEFAULT false;
ALTER TABLE targets ADD CONSTRAINT targets_p02_complete CHECK (NOT trust_metadata_complete OR (target_key IS NOT NULL AND contract_version='synthetic-redfish-v1' AND credential_provider='synthetic-test' AND credential_reference ~ '^synthetic-test:[A-Za-z0-9._-]{1,96}$' AND transport_policy_version IS NOT NULL AND registration_hash ~ '^sha256:[0-9a-f]{64}$'));
CREATE UNIQUE INDEX targets_p02_address_unique ON targets(endpoint_reference,target_key,contract_version) WHERE trust_metadata_complete;
CREATE TABLE target_labels (target_id uuid NOT NULL REFERENCES targets(id) ON DELETE RESTRICT,key varchar(63) NOT NULL,value varchar(256) NOT NULL,PRIMARY KEY(target_id,key),CONSTRAINT target_labels_key_valid CHECK(key ~ '^[a-z0-9]([a-z0-9._-]*[a-z0-9])?$'),CONSTRAINT target_labels_value_nonempty CHECK(length(value)>0));
CREATE INDEX target_labels_exact_lookup_index ON target_labels(key,value,target_id);
CREATE TABLE target_discovery_heads (target_id uuid PRIMARY KEY REFERENCES targets(id) ON DELETE RESTRICT,head_revision bigint NOT NULL DEFAULT 0,configuration_revision bigint NOT NULL DEFAULT 0,latest_attempt_id uuid REFERENCES device_observations(id) ON DELETE RESTRICT,last_good_id uuid REFERENCES device_observations(id) ON DELETE RESTRICT,next_refresh_at timestamptz,CONSTRAINT target_discovery_heads_revisions_nonnegative CHECK(head_revision>=0 AND configuration_revision>=0));
CREATE TABLE artifact_object_versions (artifact_id uuid PRIMARY KEY REFERENCES firmware_artifacts(id) ON DELETE RESTRICT,provider varchar(32) NOT NULL,container varchar(256) NOT NULL,object_key varchar(256) NOT NULL,version_id varchar(256) NOT NULL,object_size bigint NOT NULL,sha256_digest varchar(71) NOT NULL,verification_policy_version varchar(64) NOT NULL,declared_target_family varchar(256) NOT NULL,bound_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT artifact_object_versions_provider CHECK(provider='local-versioned-v1'),CONSTRAINT artifact_object_versions_identity CHECK(length(container)>0 AND length(object_key)>0 AND length(version_id)>0 AND object_key !~ '(^|/)\.\.(/|$)' AND object_key !~ '^/'),CONSTRAINT artifact_object_versions_bounds CHECK(object_size>0 AND object_size<=16777216 AND sha256_digest ~ '^sha256:[0-9a-f]{64}$' AND verification_policy_version='synthetic-sha256-v1'),CONSTRAINT artifact_object_versions_unique UNIQUE(provider,container,object_key,version_id));
CREATE TABLE artifact_verification_results (artifact_id uuid PRIMARY KEY REFERENCES firmware_artifacts(id) ON DELETE RESTRICT,object_version_id varchar(256) NOT NULL,policy_version varchar(64) NOT NULL,state text NOT NULL,reason_code varchar(128) NOT NULL,verified_digest varchar(71),verified_size bigint,verified_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT artifact_verification_results_state CHECK(state IN('VERIFIED','REJECTED')),CONSTRAINT artifact_verification_results_result CHECK((state='VERIFIED' AND verified_digest ~ '^sha256:[0-9a-f]{64}$' AND verified_size>0) OR(state='REJECTED' AND verified_digest IS NULL AND verified_size IS NULL)));
CREATE TABLE preflight_candidates (id uuid PRIMARY KEY,artifact_id uuid NOT NULL REFERENCES firmware_artifacts(id) ON DELETE RESTRICT,artifact_version_id varchar(256) NOT NULL,selector_version varchar(64) NOT NULL,selector_json jsonb NOT NULL,snapshot_hash varchar(71) NOT NULL,state text NOT NULL,report jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT preflight_candidates_valid CHECK(state IN('PASSED','BLOCKED') AND jsonb_typeof(selector_json)='object' AND jsonb_typeof(report)='object' AND octet_length(selector_json::text)<=4096 AND octet_length(report::text)<=32768 AND snapshot_hash ~ '^sha256:[0-9a-f]{64}$'));
CREATE TABLE preflight_candidate_targets (candidate_id uuid NOT NULL REFERENCES preflight_candidates(id) ON DELETE RESTRICT,target_id uuid NOT NULL REFERENCES targets(id) ON DELETE RESTRICT,frozen_target_revision bigint NOT NULL,site_key varchar(128) NOT NULL,rack_key varchar(128) NOT NULL,target_family varchar(256) NOT NULL,compatibility_policy_version varchar(64) NOT NULL,compatibility_reason varchar(128) NOT NULL,PRIMARY KEY(candidate_id,target_id),CONSTRAINT preflight_candidate_targets_valid CHECK(frozen_target_revision>=0 AND length(site_key)>0 AND length(rack_key)>0 AND length(target_family)>0));
CREATE TABLE artifact_holds (artifact_id uuid NOT NULL REFERENCES firmware_artifacts(id) ON DELETE RESTRICT,campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE RESTRICT,object_version_id varchar(256) NOT NULL,acquired_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,release_reason varchar(128),PRIMARY KEY(artifact_id,campaign_id),CONSTRAINT artifact_holds_release CHECK((released_at IS NULL AND release_reason IS NULL) OR(released_at IS NOT NULL AND release_reason IS NOT NULL)));
CREATE INDEX artifact_holds_active_index ON artifact_holds(artifact_id) WHERE released_at IS NULL;
